/*!
 * \file ai_infra_sinkhorn_grad_tiling_base.cpp
 * \brief
 */

#include "ai_infra_sinkhorn_grad_tiling.h"
#include "register/op_def_registry.h"
#include "tiling_base/tiling_base.h"
#include "tiling_base/tiling_templates_registry.h"
#include "log/log.h"
#include "kernel_tiling/kernel_tiling.h"

namespace optiling {
static ge::graphStatus TilingForAiInfraSinkhornGrad(gert::TilingContext *context)
{
    return Ops::Transformer::OpTiling::TilingRegistry::GetInstance().DoTilingImpl(context);
}

static ge::graphStatus TilingPrepareForAiInfraSinkhornGrad(gert::TilingParseContext *context)
{
    (void)context;
    return ge::GRAPH_SUCCESS;
}

IMPL_OP_OPTILING(AiInfraSinkhornGrad)
    .Tiling(TilingForAiInfraSinkhornGrad)
    .TilingParse<AiInfraSinkhornGradCompileInfo>(TilingPrepareForAiInfraSinkhornGrad);

} // namespace optiling

