30	const static int64_t DEFAULT_WORKSPACE_SIZE = 16777216;  // 预留16M
31	const static uint64_t TILING_KEY_GENERALIZED = 0;
32	
33	const static int64_t GRAD_OUTPUT_INPUT_INDEX = 0;
34	const static int64_t NORM_OUT_INPUT_INDEX = 1;
35	const static int64_t SUM_OUT_INPUT_INDEX = 2;
