59	class AiInfraSinkhornGradTilingBase : public Ops::Transformer::OpTiling::TilingBase {
60	public:
61	    explicit AiInfraSinkhornGradTilingBase(gert::TilingContext *context)
62	        : Ops::Transformer::OpTiling::TilingBase(context)
63	    {
64	        Reset();
65	    }
66	    ~AiInfraSinkhornGradTilingBase() override = default;
67	
68	    void Reset(gert::TilingContext *context) override
69	    {
70	        TilingBase::Reset(context);
71	        Reset();
72	    }
