124	ge::graphStatus AiInfraSinkhornGradTilingBase::GetPlatformInfo()
125	{
126	    auto platformInfo = context_->GetPlatformInfo();
127	    OP_CHECK_IF(platformInfo == nullptr, OP_LOGE(context_, "fail to get platform info"), return ge::GRAPH_FAILED);
128	
129	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo);
130	    aicoreParams_.blockDim = ascendcPlatform.GetCoreNumAiv();
131	    uint64_t ubSizePlatForm;
132	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSizePlatForm);
133	    aicoreParams_.ubSize = ubSizePlatForm;
134	
135	    return ge::GRAPH_SUCCESS;
136	}
