138	ge::graphStatus AiInfraSinkhornGradTilingBase::GetShapeAttrsInfo()
139	{
140	    opName_ = context_->GetNodeName();
141	
142	    // 获取输入shape信息
143	    auto gradOutputShapePtr = context_->GetInputShape(GRAD_OUTPUT_INPUT_INDEX);
144	    OP_CHECK_NULL_WITH_CONTEXT(context_, gradOutputShapePtr);
145	    gradOutputShape_ = &gradOutputShapePtr->GetStorageShape();
146	
147	    auto normOutShapePtr = context_->GetInputShape(NORM_OUT_INPUT_INDEX);
148	    OP_CHECK_NULL_WITH_CONTEXT(context_, normOutShapePtr);
149	    normOutShape_ = &normOutShapePtr->GetStorageShape();
150	
151	    auto sumOutShapePtr = context_->GetInputShape(SUM_OUT_INPUT_INDEX);
152	    OP_CHECK_NULL_WITH_CONTEXT(context_, sumOutShapePtr);
153	    sumOutShape_ = &sumOutShapePtr->GetStorageShape();
154	
155	    // 获取输出shape
156	    auto gradInputShapePtr = context_->GetOutputShape(GRAD_INPUT_OUTPUT_INDEX);
157	    OP_CHECK_NULL_WITH_CONTEXT(context_, gradInputShapePtr);
158	    gradInputShape_ = &gradInputShapePtr->GetStorageShape();
159	
160	    // 验证数据类型
161	    auto gradOutputDesc = context_->GetInputDesc(GRAD_OUTPUT_INPUT_INDEX);
162	    OP_CHECK_NULL_WITH_CONTEXT(context_, gradOutputDesc);
163	    auto gradOutputDtype = gradOutputDesc->GetDataType();
164	    OP_CHECK_IF((gradOutputDtype != ge::DataType::DT_FLOAT),
165	        OP_LOGE(context_,
166	            "grad_output dtype %s error, only supports float32. please check.",
167	            ge::TypeUtils::DataTypeToSerialString(gradOutputDtype).c_str()),
168	        return ge::GRAPH_FAILED);
169	
170	    inputDtypeSize_ = static_cast<int64_t>(ge::GetSizeByDataType(gradOutputDesc->GetDataType()));
171	
172	    auto normOutDesc = context_->GetInputDesc(NORM_OUT_INPUT_INDEX);
173	    OP_CHECK_NULL_WITH_CONTEXT(context_, normOutDesc);
174	    auto normOutDtype = normOutDesc->GetDataType();
175	    OP_CHECK_IF((normOutDtype != ge::DataType::DT_FLOAT),
176	        OP_LOGE(context_,
177	            "norm_Out dtype %s error, only supports float32. please check.",
178	            ge::TypeUtils::DataTypeToSerialString(normOutDtype).c_str()),
179	        return ge::GRAPH_FAILED);
180	
181	    auto sumOutDesc = context_->GetInputDesc(SUM_OUT_INPUT_INDEX);
182	    OP_CHECK_NULL_WITH_CONTEXT(context_, sumOutDesc);
183	    auto sumOutDtype = sumOutDesc->GetDataType();
184	    OP_CHECK_IF((sumOutDtype != ge::DataType::DT_FLOAT),
185	        OP_LOGE(context_,
186	            "sum_out dtype %s error, only supports float32. please check.",
187	            ge::TypeUtils::DataTypeToSerialString(sumOutDtype).c_str()),
188	        return ge::GRAPH_FAILED);
189	
190	    auto gradInputDesc = context_->GetOutputDesc(GRAD_INPUT_OUTPUT_INDEX);
191	    OP_CHECK_NULL_WITH_CONTEXT(context_, gradInputDesc);
192	    auto gradInputDtype = gradInputDesc->GetDataType();
193	    OP_CHECK_IF((gradInputDtype != ge::DataType::DT_FLOAT),
194	        OP_LOGE(context_,
195	            "grad_input dtype %s error, only supports float32. please check.",
196	            ge::TypeUtils::DataTypeToSerialString(gradInputDtype).c_str()),
197	        return ge::GRAPH_FAILED);
198	
199	    return ge::GRAPH_SUCCESS;
200	}
