202	ge::graphStatus AiInfraSinkhornGradTilingBase::CheckGradOutputShape()
203	{
204	    if (isTShape_) {
205	        if (gradOutputShape_->GetDim(DIM_2) != nSize_) {
206	            OP_LOGE(context_, "The dim2 and dim3 of grad_output shape should be equal.");
207	            return ge::GRAPH_FAILED;
208	        }
209	    } else {
210	        if (gradOutputShape_->GetDim(DIM_3) != nSize_) {
211	            OP_LOGE(context_, "The dim2 and dim3 of grad_output shape should be equal.");
212	            return ge::GRAPH_FAILED;
213	        }
214	    }
215	
216	    return ge::GRAPH_SUCCESS;
217	}
218	
219	ge::graphStatus AiInfraSinkhornGradTilingBase::CheckNormOutShape()
220	{
221	    if (isTShape_) {
222	        if (normOutShape_->GetDim(DIM_1) == nSize_ &&
223	            normOutShape_->GetDim(DIM_2) == nSize_ &&
224	            normOutShape_->GetDim(DIM_3) == tSize_) {
225	            return ge::GRAPH_SUCCESS;
226	        }
227	
228	        OP_LOGE(context_, "The norm_out shape is invalid, it should be {%ld, %ld, %ld, %ld}.", numIters_,
229	            nSize_, nSize_, tSize_);
230	    } else {
231	        if (normOutShape_->GetDim(DIM_1) == nSize_ &&
232	            normOutShape_->GetDim(DIM_2) == nSize_ &&
233	            normOutShape_->GetDim(DIM_3) == bSize_ &&
234	            normOutShape_->GetDim(DIM_4) == sSize_) {
235	            return ge::GRAPH_SUCCESS;
236	        }
237	
238	        OP_LOGE(context_, "The norm_out shape is invalid, it should be {%ld, %ld, %ld, %ld, %ld}.", numIters_,
239	            nSize_, nSize_, bSize_, sSize_);
240	    }
241	    return ge::GRAPH_FAILED;
242	}
243	
244	ge::graphStatus AiInfraSinkhornGradTilingBase::CheckSumOutShape()
245	{
246	    if (isTShape_) {
247	        if (sumOutShape_->GetDim(DIM_0) == 2 * numIters_ &&
248	            sumOutShape_->GetDim(DIM_1) == nSize_ &&
249	            sumOutShape_->GetDim(DIM_2) == tSize_) {
250	            return ge::GRAPH_SUCCESS;
251	        }
252	
253	        OP_LOGE(context_, "The sum_out shape is invalid, it should be {%ld, %ld, %ld}.", numIters_,
254	            nSize_, tSize_);
255	    } else {
256	        if (sumOutShape_->GetDim(DIM_0) == 2 * numIters_ &&
257	            sumOutShape_->GetDim(DIM_1) == nSize_ &&
258	            sumOutShape_->GetDim(DIM_2) == bSize_ &&
259	            sumOutShape_->GetDim(DIM_3) == sSize_) {
260	            return ge::GRAPH_SUCCESS;
261	        }
262	
263	        OP_LOGE(context_, "The sum_out shape is invalid, it should be {%ld, %ld, %ld, %ld}.", numIters_,
264	            nSize_, bSize_, sSize_);
265	    }
266	    return ge::GRAPH_FAILED;
267	}
