269	ge::graphStatus AiInfraSinkhornGradTilingBase::CheckInputShape()
270	{
271	    OP_CHECK_IF(gradOutputShape_ == nullptr,
272	        OP_LOGE(context_, "grad_output shape is null"),
273	        return ge::GRAPH_FAILED);
274	    OP_CHECK_IF(normOutShape_ == nullptr,
275	        OP_LOGE(context_, "norm_output shape is null"),
276	        return ge::GRAPH_FAILED);
277	    OP_CHECK_IF(sumOutShape_ == nullptr,
278	        OP_LOGE(context_, "sum_output shape is null"),
279	        return ge::GRAPH_FAILED);
280	
281	    isTShape_ = gradOutputShape_->GetDimNum() == GRAD_OUTPUT_INPUT_T_DIMNUM ? true : false;
282	    if (isTShape_) {
283	        if (normOutShape_->GetDimNum() != NORM_OUTPUT_INPUT_T_DIMNUM ||
284	            sumOutShape_->GetDimNum() != SUM_OUTPUT_INPUT_T_DIMNUM) {
285	            OP_LOGE(context_, "Input shape dim num is invalid");
286	            return ge::GRAPH_FAILED;
287	        }
288	        tSize_ = gradOutputShape_->GetDim(DIM_0);
289	        nSize_ = gradOutputShape_->GetDim(DIM_1);
290	        totalLength_ = tSize_;
291	    } else {
292	        if (gradOutputShape_->GetDimNum() != GRAD_OUTPUT_INPUT_BS_DIMNUM ||
293	            normOutShape_->GetDimNum() != NORM_OUTPUT_INPUT_BS_DIMNUM ||
294	            sumOutShape_->GetDimNum() != SUM_OUTPUT_INPUT_BS_DIMNUM) {
295	            OP_LOGE(context_, "Input shape dim num is invalid");
296	            return ge::GRAPH_FAILED;
297	        }
298	        bSize_ = gradOutputShape_->GetDim(DIM_0);
299	        sSize_ = gradOutputShape_->GetDim(DIM_1);
300	        nSize_ = gradOutputShape_->GetDim(DIM_2);
301	        totalLength_ = bSize_ * sSize_;
302	    }
303	    int64_t normOutDim0 = normOutShape_->GetDim(DIM_0);
304	    if (normOutDim0 & 1) {
305	        OP_LOGE(context_, "dim0 of norm_Out is expected to be even, but the current value got %ld.",
306	            normOutDim0);
307	        return ge::GRAPH_FAILED;
308	    }
309	    numIters_ = normOutDim0 / 2;
310	
311	    if (numIters_ > 100 || numIters_ < 1) {
312	        OP_LOGE(context_, "num_Iters is expected to be [1, 100], but the current value got %ld.",
313	            numIters_);
314	        return ge::GRAPH_FAILED;
315	    }
316	
317	    if (CheckGradOutputShape() != ge::GRAPH_SUCCESS ||
318	        CheckNormOutShape() != ge::GRAPH_SUCCESS ||
319	        CheckSumOutShape() != ge::GRAPH_SUCCESS) {
320	        return ge::GRAPH_FAILED;
321	    }
322	    
323	    tilingData_.set_totalLength(totalLength_);
324	    tilingData_.set_n(nSize_);
325	    tilingData_.set_numIters(numIters_);
326	
327	    OP_LOGI(context_, "total_length=%ld, n=%ld, numIters=%ld", totalLength_, nSize_, numIters_);
328	
329	    return ge::GRAPH_SUCCESS;
330	}
