332	ge::graphStatus AiInfraSinkhornGradTilingBase::CheckOutputShape()
333	{
334	    OP_CHECK_IF(gradInputShape_ == nullptr,
335	        OP_LOGE(context_, "grad_intput shape is null"),
336	        return ge::GRAPH_FAILED);
337	    if (isTShape_) {
338	        if (gradInputShape_->GetDimNum() != GRAD_INPUT_OUTPUT_T_DIMNUM) {
339	            OP_LOGE(context_, "grad_intput shape dim num is invalid");
340	            return ge::GRAPH_FAILED;
341	        }
342	    } else {
343	        if (gradInputShape_->GetDimNum() != GRAD_INPUT_OUTPUT_BS_DIMNUM) {
344	            OP_LOGE(context_, "grad_intput shape dim num is invalid");
345	            return ge::GRAPH_FAILED;
346	        }
347	    }
348	
349	    if (isTShape_) {
350	        if (gradInputShape_->GetDim(DIM_0) == tSize_ &&
351	            gradInputShape_->GetDim(DIM_1) == nSize_ &&
352	            gradInputShape_->GetDim(DIM_2) == nSize_) {
353	            return ge::GRAPH_SUCCESS;
354	        }
355	
356	        OP_LOGE(context_, "The grad_input shape is invalid, it should be {%ld, %ld, %ld}.", tSize_,
357	            nSize_, nSize_);
358	    } else {
359	        if (gradInputShape_->GetDim(DIM_0) == bSize_ &&
360	            gradInputShape_->GetDim(DIM_1) == sSize_ &&
361	            gradInputShape_->GetDim(DIM_2) == nSize_ &&
362	            gradInputShape_->GetDim(DIM_3) == nSize_) {
363	            return ge::GRAPH_SUCCESS;
364	        }
365	
366	        OP_LOGE(context_, "The grad_input shape is invalid, it should be {%ld, %ld, %ld, %ld}.", bSize_,
367	            sSize_, nSize_, nSize_);
368	    }
369	
370	    return ge::GRAPH_FAILED;
371	}
