373	ge::graphStatus AiInfraSinkhornGradTilingBase::SplitCores()
374	{
375	    // UB 分配计算：(7nnt + 3nt) * 4B < 可用UB大小
376	    // gradInQueue(1): tnn, normInQueue(2): 2tnn, sumInQueue(2): 2tn
377	    // gradOutQueue(1): tnn, tmpBuffer(1): 3tnn + tn
378	    // 总共: 7tnn + 3t*n
379	
380	    int64_t maxTokensPerLoop = AVALABLE_UB_SIZE / (DTYPE_SIZE * (7 * nSize_ * nSize_ + 3 * nSize_));
381	    maxTokensPerLoop = maxTokensPerLoop & ~0x7;
382	
383	    if (maxTokensPerLoop < TRANSPOSE_BUFFER_SIZE) {
384	        maxTokensPerLoop = (AVALABLE_UB_SIZE - DTYPE_SIZE * TRANSPOSE_BUFFER_SIZE * (2 * nSize_ * nSize_ + nSize_)) /
385	            (DTYPE_SIZE * (5 * nSize_ * nSize_ + 2 * nSize_));
386	        maxTokensPerLoop = maxTokensPerLoop & ~0x7;
387	    }
388	
389	    OP_CHECK_IF(maxTokensPerLoop < 8,
390	        OP_LOGE(context_, "UB size is not enough for n=%ld", nSize_),
391	        return ge::GRAPH_FAILED);
392	
393	    // 核间切分：在 T 维度上进行核间切分
394	    int64_t aivNum = static_cast<int64_t>(aicoreParams_.blockDim);
395	    // 初始按所有核平均分配
396	    int64_t perCoreElements = CeilDiv(totalLength_, aivNum);
397	    // 限核策略：当 perCoreElements 较小时（< 32），通过提高 perCoreElements 下限来减少使用的核数
398	    if (perCoreElements < MIN_PER_CORE_ELEMENTS && totalLength_ >= MIN_PER_CORE_ELEMENTS) {
399	        perCoreElements = MIN_PER_CORE_ELEMENTS;
400	    }
401	
402	    // 核内切分：普通核
403	    int64_t perCoreLoops = CeilDiv(perCoreElements, maxTokensPerLoop);
404	    if (perCoreLoops == 1) {
405	        perCoreElements = (perCoreElements + 0x7) & ~0x7;
406	    }
407	    int64_t perCorePerLoopElements = perCoreElements < maxTokensPerLoop ? perCoreElements : maxTokensPerLoop;
408	    int64_t perCoreLastLoopElements = perCoreElements - (perCoreLoops - 1) * perCorePerLoopElements;
409	
410	    int64_t needCoreNum = CeilDiv(totalLength_, perCoreElements);
411	    int64_t lastCoreElements = totalLength_ - perCoreElements * (needCoreNum - 1);
412	
413	    // 核内切分：最后一个核
414	    int64_t lastCoreLoops = CeilDiv(lastCoreElements, maxTokensPerLoop);
415	    int64_t lastCorePerLoopElements = lastCoreElements < maxTokensPerLoop ? lastCoreElements : maxTokensPerLoop;
416	    int64_t lastCoreLastLoopElements = lastCoreElements - (lastCoreLoops - 1) * lastCorePerLoopElements;
417	    // 设置 tilingData
418	    tilingData_.set_needCoreNum(needCoreNum);
419	    tilingData_.set_perCoreElements(perCoreElements);
420	    tilingData_.set_lastCoreElements(lastCoreElements);
421	    tilingData_.set_perCoreLoops(perCoreLoops);
422	    tilingData_.set_perCorePerLoopElements(perCorePerLoopElements);
423	    tilingData_.set_perCoreLastLoopElements(perCoreLastLoopElements);
424	    tilingData_.set_lastCoreLoops(lastCoreLoops);
425	    tilingData_.set_lastCorePerLoopElements(lastCorePerLoopElements);
426	    tilingData_.set_lastCoreLastLoopElements(lastCoreLastLoopElements);
427	
428	    OP_LOGI(context_, "Core splitting: needCoreNum=%ld, perCoreElements=%ld, lastCoreElements=%ld, "
429	        "maxTokensPerLoop=%ld, perCoreLoops=%ld, perCorePerLoopElements=%ld, perCoreLastLoopElements=%ld, "
430	        "lastCoreLoops=%ld, lastCorePerLoopElements=%ld, lastCoreLastLoopElements=%ld",
431	        needCoreNum, perCoreElements, lastCoreElements,
432	        maxTokensPerLoop, perCoreLoops, perCorePerLoopElements, perCoreLastLoopElements,
433	        lastCoreLoops, lastCorePerLoopElements, lastCoreLastLoopElements);
434	    return ge::GRAPH_SUCCESS;
435	}
