437	ge::graphStatus AiInfraSinkhornGradTilingBase::DoOpTiling()
438	{
439	    auto ret = CheckInputShape();
440	    if (ret != ge::GRAPH_SUCCESS) {
441	    return ret;
442	    }
443	
444	    ret = CheckOutputShape();
445	    if (ret != ge::GRAPH_SUCCESS) {
446	        return ret;
447	    }
448	
449	    ret = SplitCores();
450	    if (ret != ge::GRAPH_SUCCESS) {
451	        return ret;
452	    }
453	
454	    return ge::GRAPH_SUCCESS;
455	}
