462	ge::graphStatus AiInfraSinkhornGradTilingBase::GetWorkspaceSize()
463	{
464	    // 计算 workspace 大小
465	    workspaceSize_ = DEFAULT_WORKSPACE_SIZE;
466	    return ge::GRAPH_SUCCESS;
467	}
