469	ge::graphStatus AiInfraSinkhornGradTilingBase::PostTiling()
470	{
471	    context_->SetBlockDim(tilingData_.get_needCoreNum());
472	    size_t *currentWorkspace = context_->GetWorkspaceSizes(1);
473	    currentWorkspace[0] = workspaceSize_;
474	    tilingData_.SaveToBuffer(context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity());
475	    context_->GetRawTilingData()->SetDataSize(tilingData_.GetDataSize());
476	    return ge::GRAPH_SUCCESS;
477	}
