11	/*!
12	 * \file ai_infra_sinkhorn_grad_generalized.cpp
13	 * \brief
14	 */
15	
16	#ifndef AI_INFRA_SINKHORN_GRAD_GENERALIZED_H
17	#define AI_INFRA_SINKHORN_GRAD_GENERALIZED_H
18	#include "kernel_operator.h"
19	#include "kernel_utils.h"
20	#include "kernel_tiling/kernel_tiling.h"
21	
22	namespace AiInfraSinkhornGrad {
23	using namespace AscendC;
24	
25	constexpr int64_t BLOCK_BYTES = 32;
26	constexpr int64_t TRANSPOSE_BUFFER_FACTOR = 128;
27	constexpr int64_t CONSTANT_TWO = 2;
28	constexpr int64_t BUFFER_TWO = 2;
29	
30	__aicore__ inline int64_t Ceil(int64_t a, int64_t b)
31	{
32	    if (b == 0) {
33	        return 0;
34	    }
35	    return (a + b - 1) / b;
36	}
37	
38	__aicore__ inline int64_t Min(int64_t a, int64_t b)
39	{
40	    return (a < b) ? a : b;
41	}
42	
43	__aicore__ inline int64_t Align(int64_t elementNum, int64_t bytes)
44	{
45	    if (bytes == 0) {
46	        return 0;
47	    }
48	    return (elementNum * bytes + BLOCK_BYTES - 1) / BLOCK_BYTES * BLOCK_BYTES / bytes;
49	}
50	
51	__aicore__ inline int64_t AlignBytes(int64_t elementNum, int64_t bytes)
52	{
53	    return (elementNum * bytes + BLOCK_BYTES - 1) / BLOCK_BYTES * BLOCK_BYTES;
54	}
55	
56	class AiInfraSinkhornGradGeneralized {
57	  public:
58	    __aicore__ inline AiInfraSinkhornGradGeneralized(){};
59	    __aicore__ inline void Init(GM_ADDR gradOutput,
60	                                GM_ADDR normOut,
61	                                GM_ADDR sumOut,
62	                                GM_ADDR gradInput,
63	                                GM_ADDR workspace,
64	                                const AiInfraSinkhornGradTilingData *__restrict__ tilingData,
65	                                TPipe *tPipe);
66	    __aicore__ inline void Process();
67	
68	  private:
69	    __aicore__ inline void CopyInX(int64_t offset);
70	    __aicore__ inline void TransposeXIn();
71	    __aicore__ inline void CopyInNormOut(int64_t offset);
72	    __aicore__ inline void CopyInSumOut(int64_t offset);
73	    __aicore__ inline void colNormGrad();
74	    __aicore__ inline void rowNormGrad();
75	    __aicore__ inline void softmaxGrad();
76	    __aicore__ inline void TransposeXOut();
77	    __aicore__ inline void CopyOut(int64_t offset);
78	
79	  private:
80	    TPipe *pipe_;
81	    TQue<QuePosition::VECIN, 1> gradInQueue_;
82	    TQue<QuePosition::VECIN, 2> normInQueue_;
83	    TQue<QuePosition::VECIN, 2> sumInQueue_;
84	    TQue<QuePosition::VECOUT, 1> gradOutQueue_;
85	    TBuf<TPosition::VECCALC> calcTmpBuf_;
86	    TBuf<TPosition::VECCALC> gradTransposeBuf_;
87	
88	    GlobalTensor<float> gradOutputGm_;
89	    GlobalTensor<float> normOutGm_;
90	    GlobalTensor<float> sumOutGm_;
91	    GlobalTensor<float> gradInputGm_;
92	
93	    int64_t totalLength_;
94	    int64_t n_;
95	    int64_t numIters_;
96	    int64_t needCoreNum_;
97	    int64_t tAlign_;
98	
99	    // 核间切分
100	    int64_t perCoreElements_;
101	    int64_t lastCoreElements_;
102	    int64_t blockIdx_;
103	
104	    // 核内切分
105	    int64_t perCoreLoops_;
106	    int64_t perCorePerLoopElements_;
107	    int64_t perCoreLastLoopElements_;
108	    int64_t lastCoreLoops_;
109	    int64_t lastCorePerLoopElements_;
110	    int64_t lastCoreLastLoopElements_;
111	
112	    // 当前核的tiling策略
113	    int64_t currentCoreElements_;
114	    int64_t currentCoreloops_;
115	    int64_t currentCorePerLoopElements_;
116	    int64_t currentCoreLastLoopElements_;
117	
118	    int64_t currentLoopElements_;
119	    const AiInfraSinkhornGradTilingData *__restrict__ tilingData_;
120	};
121	
122	__aicore__ inline void AiInfraSinkhornGradGeneralized::Init(GM_ADDR gradOutput,
123	                                     GM_ADDR normOut,
124	                                     GM_ADDR sumOut,
125	                                     GM_ADDR gradInput,
126	                                     GM_ADDR workspace,
127	                                     const AiInfraSinkhornGradTilingData *__restrict__ tilingData,
128	                                     TPipe *tPipe)
129	{
130	    pipe_ = tPipe;
131	    tilingData_ = tilingData;
132	    totalLength_ = tilingData->totalLength;
133	    n_ = tilingData->n;
134	    numIters_ = tilingData->numIters;
135	    needCoreNum_ = tilingData->needCoreNum;
136	    perCoreElements_ = tilingData->perCoreElements;
137	    lastCoreElements_ = tilingData->lastCoreElements;
138	
139	    perCoreLoops_ = tilingData->perCoreLoops;
140	    perCorePerLoopElements_ = tilingData->perCorePerLoopElements;
141	    perCoreLastLoopElements_ = tilingData->perCoreLastLoopElements;
142	    lastCoreLoops_ = tilingData->lastCoreLoops;
143	    lastCorePerLoopElements_ = tilingData->lastCorePerLoopElements;
144	    lastCoreLastLoopElements_ = tilingData->lastCoreLastLoopElements;
145	
146	    blockIdx_ = GetBlockIdx();
147	    currentCoreElements_ = (blockIdx_ < needCoreNum_ - 1) ? perCoreElements_ : lastCoreElements_;
148	    currentCoreloops_ = (blockIdx_ < needCoreNum_ - 1) ? perCoreLoops_ : lastCoreLoops_;
149	    currentCorePerLoopElements_ = (blockIdx_ < needCoreNum_ - 1) ? perCorePerLoopElements_ : lastCorePerLoopElements_;
150	    currentCoreLastLoopElements_ =
151	        (blockIdx_ < needCoreNum_ - 1) ? perCoreLastLoopElements_ : lastCoreLastLoopElements_;
152	
153	    tAlign_ = Align(perCorePerLoopElements_, sizeof(float));
154	    pipe_->InitBuffer(gradInQueue_, 1, tAlign_ * n_ * n_ * sizeof(float));
155	    pipe_->InitBuffer(normInQueue_, BUFFER_TWO, tAlign_ * n_ * n_ * sizeof(float));
156	    pipe_->InitBuffer(sumInQueue_, BUFFER_TWO, tAlign_ * n_ * sizeof(float));
157	    pipe_->InitBuffer(gradOutQueue_, 1, tAlign_ * n_ * n_ * sizeof(float));
158	
159	    int64_t transposeBuf = AlignBytes((n_ * n_ * CONSTANT_TWO + 1) * TRANSPOSE_BUFFER_FACTOR, sizeof(float));
160	    int64_t bufferSize = tAlign_ * n_ * n_ * CONSTANT_TWO * sizeof(float) + tAlign_ * n_ * sizeof(float);
161	    if (bufferSize >= transposeBuf) {
162	        pipe_->InitBuffer(calcTmpBuf_, bufferSize);
163	    } else {
164	        pipe_->InitBuffer(calcTmpBuf_, transposeBuf);
165	    }
166	    pipe_->InitBuffer(gradTransposeBuf_, tAlign_ * n_ * n_ * sizeof(float));
167	
168	    int64_t Offset = blockIdx_ * perCoreElements_ * n_ * n_;
169	    gradOutputGm_.SetGlobalBuffer((__gm__ float *)gradOutput + Offset, currentCoreElements_ * n_ * n_);
170	    normOutGm_.SetGlobalBuffer((__gm__ float *)normOut);
171	    sumOutGm_.SetGlobalBuffer((__gm__ float *)sumOut);
172	    gradInputGm_.SetGlobalBuffer((__gm__ float *)gradInput + Offset, currentCoreElements_ * n_ * n_);
173	}
174	
175	__aicore__ inline void AiInfraSinkhornGradGeneralized::Process()
176	{
177	    if (blockIdx_ >= needCoreNum_) {
178	        return;
179	    }
180	    // 一次归一化产生的normOut矩阵大小
181	    int64_t normOutBlockLen = n_ * n_ * totalLength_;
182	    // 一次归一化产生的sumOut矩阵大小
183	    int64_t sumOutBlockLen = n_ * totalLength_;
184	
185	    for (int i = 0; i < currentCoreloops_; ++i) {
186	        // 当前核当前loop处理的token数
187	        currentLoopElements_ =
188	            (i == currentCoreloops_ - 1) ? currentCoreLastLoopElements_ : currentCorePerLoopElements_;
189	        // 核内grad_output GM核内偏移, 初始化时已增加核间偏移
190	        int64_t offset = i * currentCorePerLoopElements_ * n_ * n_;
191	        // normOut与sumOut在GM上最后一个维度上t的偏移
192	        int64_t tOffset = blockIdx_ * perCoreElements_ + i * currentCorePerLoopElements_;
193	        int64_t normOffset = 0;
194	        int64_t sumOffset = 0;
195	
196	        // 拷入并转置
197	        CopyInX(offset);
198	        TransposeXIn();
199	
200	        for (int j = numIters_ - 1; j > 0; --j) {
201	            int64_t colOffset = 2 * j + 1;
202	            int64_t rowOffset = 2 * j;
203	
204	            // 列归一化
205	            normOffset = colOffset * normOutBlockLen + tOffset;
206	            sumOffset = colOffset * sumOutBlockLen + tOffset;
207	            CopyInNormOut(normOffset);
208	            CopyInSumOut(sumOffset);
209	            colNormGrad();
210	
211	            // 行归一化
212	            normOffset = rowOffset * normOutBlockLen + tOffset;
213	            sumOffset = rowOffset * sumOutBlockLen + tOffset;
214	            CopyInNormOut(normOffset);
215	            CopyInSumOut(sumOffset);
216	            rowNormGrad();
217	        }
218	
219	        // 列最后一次归一化
220	        normOffset = 1 * normOutBlockLen + tOffset;
221	        sumOffset = 1 * sumOutBlockLen + tOffset;
222	        CopyInNormOut(normOffset);
223	        CopyInSumOut(sumOffset);
224	        colNormGrad();
225	
226	        // 行最后归一化
227	        normOffset = 0 * normOutBlockLen + tOffset;
228	        CopyInNormOut(normOffset);
229	        softmaxGrad();
230	
231	        // 转置搬出
232	        TransposeXOut();
233	        CopyOut(offset);
234	    }
235	}
236	
237	__aicore__ inline void AiInfraSinkhornGradGeneralized::CopyInX(int64_t offset)
238	{
239	    // 拷入[t, n, n] grad
240	    LocalTensor<float> gradLocal = gradInQueue_.AllocTensor<float>();
241	    DataCopyExtParams dataCopyParams{
242	        static_cast<uint16_t>(1), static_cast<uint32_t>(currentLoopElements_ * n_ * n_ * sizeof(float)), 0, 0, 0};
243	    DataCopyPadExtParams<float> dataCopyPadParams{false, 0, 0, 0};
244	    DataCopyPad(gradLocal, gradOutputGm_[offset], dataCopyParams, dataCopyPadParams);
245	    gradInQueue_.EnQue(gradLocal);
246	}
247	
248	__aicore__ inline void AiInfraSinkhornGradGeneralized::TransposeXIn()
249	{
250	    // [t, n, n] grad转换为[n, n, t]
251	    LocalTensor<float> gradLocal = gradInQueue_.DeQue<float>();
252	    LocalTensor<float> gradTranspose = gradTransposeBuf_.Get<float>();
253	
254	    auto h0 = 16;
255	    auto w0 = 32 / sizeof(float);
256	    auto tmpBufferSize = (n_ * n_ * 2 + 1) * h0 * w0;
257	    LocalTensor<uint8_t> stackBuffer = calcTmpBuf_.Get<uint8_t>(tmpBufferSize);
258	
259	    TransposeParamsExt transposeParams;
260	    transposeParams.nSize = 1;
261	    transposeParams.cSize = n_ * n_;
262	    transposeParams.hSize = 1;
263	    transposeParams.wSize = tAlign_;
264	    transposeParams.transposeType = TransposeType::TRANSPOSE_NHWC2NCHW;
265	    Transpose(gradTranspose, gradLocal, stackBuffer, transposeParams);
266	    PipeBarrier<PIPE_V>();
267	    gradInQueue_.FreeTensor(gradLocal);
268	}
269	
270	__aicore__ inline void AiInfraSinkhornGradGeneralized::TransposeXOut()
271	{
272	    // [n, n, t] grad转换为[t, n, n]
273	    LocalTensor<float> gradLocal = gradTransposeBuf_.Get<float>();
274	    LocalTensor<float> gradTranspose = gradOutQueue_.AllocTensor<float>();
275	
276	    auto h0 = 16;
277	    auto w0 = 32 / sizeof(float);
278	    auto tmpBufferSize = (n_ * n_ + 2) * h0 * w0;
279	    LocalTensor<uint8_t> stackBuffer = calcTmpBuf_.Get<uint8_t>(tmpBufferSize);
280	
281	    TransposeParamsExt transposeParams;
282	    transposeParams.nSize = 1;
283	    transposeParams.cSize = n_ * n_;
284	    transposeParams.hSize = 1;
285	    transposeParams.wSize = tAlign_;
286	    transposeParams.transposeType = TransposeType::TRANSPOSE_NCHW2NHWC;
287	    Transpose(gradTranspose, gradLocal, stackBuffer, transposeParams);
288	    PipeBarrier<PIPE_V>();
289	    gradOutQueue_.EnQue(gradTranspose);
290	}
291	
292	/**
293	     * @brief normOut在GM上的排序shape是[2*numIters, n, n, T], 需要尾轴切分拷入
294	     */
295	__aicore__ inline void AiInfraSinkhornGradGeneralized::CopyInNormOut(int64_t offset)
296	{
297	    uint16_t blockCount = static_cast<uint16_t>(n_ * n_);
298	    uint32_t blockLen = static_cast<uint32_t>(currentLoopElements_ * sizeof(float));
299	    uint32_t srcStride = static_cast<uint32_t>((totalLength_ - currentLoopElements_) * sizeof(float));
300	    uint32_t dstStride = static_cast<uint32_t>((tAlign_ - currentLoopElements_) * sizeof(float) / BLOCK_BYTES);
301	    DataCopyExtParams dataCopyParams{blockCount, blockLen, srcStride, dstStride, 0};
302	    DataCopyPadExtParams<float> dataCopyPadParams{false, 0, 0, 0};
303	
304	    LocalTensor<float> normLocal = normInQueue_.AllocTensor<float>();
305	    DataCopyPad(normLocal, normOutGm_[offset], dataCopyParams, dataCopyPadParams);
306	    normInQueue_.EnQue(normLocal);
307	}
308	
309	/**
310	     * @brief SumOut在GM上的排序shape是[2*numIters, n, T], 需要尾轴切分拷入
311	     */
312	__aicore__ inline void AiInfraSinkhornGradGeneralized::CopyInSumOut(int64_t offset)
313	{
314	    uint16_t blockCount = static_cast<uint16_t>(n_);
315	    uint32_t blockLen = static_cast<uint32_t>(currentLoopElements_ * sizeof(float));
316	    uint32_t srcStride = static_cast<uint32_t>((totalLength_ - currentLoopElements_) * sizeof(float));
317	    uint32_t dstStride = static_cast<uint32_t>((tAlign_ - currentLoopElements_) * sizeof(float) / BLOCK_BYTES);
318	    DataCopyExtParams dataCopyParams{blockCount, blockLen, srcStride, dstStride, 0};
319	    DataCopyPadExtParams<float> dataCopyPadParams{false, 0, 0, 0};
320	
321	    LocalTensor<float> sumLocal = sumInQueue_.AllocTensor<float>();
322	    DataCopyPad(sumLocal, sumOutGm_[offset], dataCopyParams, dataCopyPadParams);
323	    sumInQueue_.EnQue(sumLocal);
324	}
325	
326	__aicore__ inline void AiInfraSinkhornGradGeneralized::colNormGrad()
327	{
328	    // 1. grad * normOut
329	    // 2. dot_prod = reduceSum(grad * normOut)
330	    // 3. grad - dot_prod
331	    // 4. (grad - dot_prod) / sumOut
332	    LocalTensor<float> gradLocal = gradTransposeBuf_.Get<float>();
333	    LocalTensor<float> normLocal = normInQueue_.DeQue<float>();
334	    LocalTensor<float> sumLocal = sumInQueue_.DeQue<float>();
335	
336	    int64_t nt = tAlign_ * n_;
337	    int64_t nnt = n_ * nt;
338	    LocalTensor<float> mulResultTensor = calcTmpBuf_.GetWithOffset<float>(nnt, 0);
339	    LocalTensor<float> dot_prod = calcTmpBuf_.GetWithOffset<float>(nt, nnt * sizeof(float));
340	    LocalTensor<float> subResultTensor =
341	        calcTmpBuf_.GetWithOffset<float>(nnt, nnt * sizeof(float) + nt * sizeof(float));
342	
343	    Mul(mulResultTensor, gradLocal, normLocal, nnt);
344	    PipeBarrier<PIPE_V>();
345	    uint32_t shape[] = {static_cast<uint32_t>(n_), static_cast<uint32_t>(tAlign_ * n_)};
346	    // 列方向求和, Pattern::Reduce::RA表示按第一个维度求和
347	    ReduceSum<float, Pattern::Reduce::RA, true>(dot_prod, mulResultTensor, shape, true);
348	    PipeBarrier<PIPE_V>();
349	    for (int i = 0; i < n_; ++i) {
350	        Sub(subResultTensor[i * nt], gradLocal[i * nt], dot_prod, nt);
351	        PipeBarrier<PIPE_V>();
352	        Div(gradLocal[i * nt], subResultTensor[i * nt], sumLocal, nt);
353	    }
354	    PipeBarrier<PIPE_V>();
355	    normInQueue_.FreeTensor(normLocal);
356	    sumInQueue_.FreeTensor(sumLocal);
357	}
358	
359	__aicore__ inline void AiInfraSinkhornGradGeneralized::rowNormGrad()
360	{
361	    // 1. grad * normOut
362	    // 2. dot_prod = sum
363	    // 3. grad - dot_prod
364	    // 4. (grad - dot_prod) / sumOut
365	    LocalTensor<float> gradLocal = gradTransposeBuf_.Get<float>();
366	    LocalTensor<float> normLocal = normInQueue_.DeQue<float>();
367	    LocalTensor<float> sumLocal = sumInQueue_.DeQue<float>();
368	
369	    int64_t nt = tAlign_ * n_;
370	    int64_t nnt = n_ * nt;
371	    LocalTensor<float> mulResultTensor = calcTmpBuf_.GetWithOffset<float>(nnt, 0);
372	    LocalTensor<float> dot_prod = calcTmpBuf_.GetWithOffset<float>(nt, nnt * sizeof(float));
373	    LocalTensor<float> subResultTensor =
374	        calcTmpBuf_.GetWithOffset<float>(nnt, nnt * sizeof(float) + nt * sizeof(float));
375	
376	    Mul(mulResultTensor, gradLocal, normLocal, nnt);
377	    PipeBarrier<PIPE_V>();
378	    uint32_t shape[] = {static_cast<uint32_t>(n_), static_cast<uint32_t>(tAlign_)};
379	    // 行方向求和
380	    for (int i = 0; i < n_; ++i) {
381	        ReduceSum<float, Pattern::Reduce::RA, true>(
382	            dot_prod[i * tAlign_], mulResultTensor[i * tAlign_ * n_], shape, true);
383	    }
384	    PipeBarrier<PIPE_V>();
385	    for (int i = 0; i < n_; ++i) {
386	        int64_t rowOffset = i * nt;
387	        for (int j = 0; j < n_; ++j) {
388	            int64_t offset = rowOffset + j * tAlign_;
389	            Sub(subResultTensor[offset], gradLocal[offset], dot_prod[i * tAlign_], tAlign_);
390	            PipeBarrier<PIPE_V>();
391	            Div(gradLocal[offset], subResultTensor[offset], sumLocal[i * tAlign_], tAlign_);
392	        }
393	    }
394	    PipeBarrier<PIPE_V>();
395	    normInQueue_.FreeTensor(normLocal);
396	    sumInQueue_.FreeTensor(sumLocal);
397	}
398	
399	__aicore__ inline void AiInfraSinkhornGradGeneralized::softmaxGrad()
400	{
401	    // 1. grad * normOut
402	    // 2. dot_prod = sum
403	    // 3. grad - dot_prod
404	    // 4. (grad - dot_prod) * normOut
405	    LocalTensor<float> gradLocal = gradTransposeBuf_.Get<float>();
406	    LocalTensor<float> normLocal = normInQueue_.DeQue<float>();
407	
408	    int64_t nt = tAlign_ * n_;
409	    int64_t nnt = n_ * nt;
410	    LocalTensor<float> mulResultTensor = calcTmpBuf_.GetWithOffset<float>(nnt, 0);
411	    LocalTensor<float> dot_prod = calcTmpBuf_.GetWithOffset<float>(nt, nnt * sizeof(float));
412	    LocalTensor<float> subResultTensor =
413	        calcTmpBuf_.GetWithOffset<float>(nnt, nnt * sizeof(float) + nt * sizeof(float));
414	
415	    Mul(mulResultTensor, gradLocal, normLocal, nnt);
416	    PipeBarrier<PIPE_V>();
417	    uint32_t shape[] = {static_cast<uint32_t>(n_), static_cast<uint32_t>(tAlign_)};
418	
419	    // 行与行求和
420	    for (int i = 0; i < n_; ++i) {
421	        ReduceSum<float, Pattern::Reduce::RA, true>(
422	            dot_prod[i * tAlign_], mulResultTensor[i * tAlign_ * n_], shape, true);
423	    }
424	    PipeBarrier<PIPE_V>();
425	
426	    for (int i = 0; i < n_; ++i) {
427	        int64_t rowOffset = i * nt;
428	        for (int j = 0; j < n_; ++j) {
429	            int64_t offset = rowOffset + j * tAlign_;
430	            Sub(subResultTensor[offset], gradLocal[offset], dot_prod[i * tAlign_], tAlign_);
431	        }
432	    }
433	    PipeBarrier<PIPE_V>();
434	    Mul(gradLocal, subResultTensor, normLocal, nnt);
435	    PipeBarrier<PIPE_V>();
436	    normInQueue_.FreeTensor(normLocal);
437	}
438	
439	__aicore__ inline void AiInfraSinkhornGradGeneralized::CopyOut(int64_t offset)
440	{
441	    LocalTensor<float> gradLocal = gradOutQueue_.DeQue<float>();
442	    DataCopyExtParams copyParams{
443	        static_cast<uint16_t>(1), static_cast<uint32_t>(currentLoopElements_ * n_ * n_ * sizeof(float)), 0, 0, 0};
444	    DataCopyPad(gradInputGm_[offset], gradLocal, copyParams);
445	    gradOutQueue_.FreeTensor(gradLocal);
446	}
447	} // namespace AiInfraSinkhornGrad
448	#endif

